#include <iostream>
#include <cstdio>
#include <cstring>
#include <queue>
#include <vector>
#include <cassert>
#include <cmath>
#include <string>
#include <algorithm>

using namespace std;

typedef long long ll;
typedef unsigned long long ull;
typedef long double ld;

const double EPS = 1e-9;
const double PI = acos(-1.0);
const int MOD = 1000000007;
const int INF = 2000000000;
const int MAXN = 210;
const int MAXM = 2 * MAXN * MAXN;
const int dx[] = {1, 0, 0, -1};
const int dy[] = {0, 1, -1, 0};
const int SRC = MAXN - 2;
const int DST = MAXN - 1;

inline int square(int x) { return x * x; }

struct FlowGraph {
    int dest[MAXM];
    int flow[MAXM], capacity[MAXM];
    int edgeCount;

    vector<int> adj[MAXN];
    bool visited[MAXN];

    FlowGraph() : edgeCount(0) {}

    void addEdge(int u, int v, int cap) {
        dest[edgeCount] = v;
        flow[edgeCount] = 0;
        capacity[edgeCount] = cap;
        adj[u].push_back(edgeCount++);

        dest[edgeCount] = u;
        flow[edgeCount] = 0;
        capacity[edgeCount] = 0;
        adj[v].push_back(edgeCount++);
    }

    bool findPath(int node, int target, int amount) {
        if (node == target) return true;
        visited[node] = true;

        for (int idx : adj[node]) {
            if (!visited[dest[idx]] && capacity[idx] - flow[idx] >= amount &&
                findPath(dest[idx], target, amount)) {
                flow[idx] += amount;
                flow[idx ^ 1] -= amount;
                return true;
            }
        }
        return false;
    }

    int compute(int source, int sink) {
        int amount = 1 << 30;
        int total = 0;

        while (amount > 0) {
            if (findPath(source, sink, amount)) {
                total += amount;
            } else {
                amount >>= 1;
            }
            memset(visited, false, sizeof visited);
        }
        return total;
    }
};

FlowGraph graph;

int n, t;
char A[15][15];
char B[15][15];
int dist[15][15];
bool used[15][15];

bool safe(int x, int y) {
    return 0 <= x && x < n &&
           0 <= y && y < n &&
           A[x][y] != 'Y' &&
           A[x][y] != 'Z';
}

void bfsFromZ(int sx, int sy) {
    for (int i = 0; i < n; ++i)
        for (int j = 0; j < n; ++j)
            dist[i][j] = INF;

    queue<int> qx, qy;
    dist[sx][sy] = 0;
    qx.push(sx);
    qy.push(sy);

    while (!qx.empty()) {
        assert(!qy.empty());
        int cx = qx.front(); qx.pop();
        int cy = qy.front(); qy.pop();

        for (int k = 0; k < 4; ++k) {
            int nx = cx + dx[k];
            int ny = cy + dy[k];
            if (safe(nx, ny) && dist[nx][ny] == INF) {
                dist[nx][ny] = dist[cx][cy] + 1;
                qx.push(nx);
                qy.push(ny);
            }
        }
    }
}

void bfsFromSource(int sx, int sy) {
    queue<int> qx, qy, qlev;
    memset(used, false, sizeof used);

    used[sx][sy] = true;
    qx.push(sx);
    qy.push(sy);
    qlev.push(0);

    while (!qx.empty()) {
        assert(!qy.empty());
        int cx = qx.front(); qx.pop();
        int cy = qy.front(); qy.pop();
        int lev = qlev.front(); qlev.pop();

        if (isdigit(B[cx][cy]) && B[cx][cy] != '0') {
            graph.addEdge(sx * n + sy, square(n) + 1 + cx * n + cy, INF);
        }

        if (lev >= t) continue;

        for (int k = 0; k < 4; ++k) {
            int nx = cx + dx[k];
            int ny = cy + dy[k];

            if (safe(nx, ny) && !used[nx][ny]) {
                if (dist[nx][ny] > lev + 1) {
                    qx.push(nx);
                    qy.push(ny);
                    qlev.push(lev + 1);
                } else if (dist[nx][ny] > lev && isdigit(B[nx][ny]) && B[nx][ny] != '0') {
                    graph.addEdge(sx * n + sy, square(n) + 1 + nx * n + ny, INF);
                }
                used[nx][ny] = true;
            }
        }
    }
}

void construct() {
    int sx = -1, sy = -1;
    for (int i = 0; i < n && sx == -1; ++i)
        for (int j = 0; j < n && sx == -1; ++j)
            if (A[i][j] == 'Z') {
                sx = i; sy = j;
            }

    bfsFromZ(sx, sy);

    for (int i = 0; i < n; ++i)
        for (int j = 0; j < n; ++j)
            if (isdigit(A[i][j]) && A[i][j] != '0')
                graph.addEdge(SRC, i * n + j, A[i][j] - '0');

    for (int i = 0; i < n; ++i)
        for (int j = 0; j < n; ++j)
            if (isdigit(B[i][j]) && B[i][j] != '0')
                graph.addEdge(i * n + j + square(n) + 1, DST, B[i][j] - '0');

    for (int i = 0; i < n; ++i)
        for (int j = 0; j < n; ++j)
            if (isdigit(A[i][j]) && A[i][j] != '0')
                bfsFromSource(i, j);
}

int main() {
#ifndef ONLINE_JUDGE
    freopen("in", "r", stdin);
#endif

    scanf("%d %d", &n, &t);
    scanf("\n");
    for (int i = 0; i < n; ++i) gets(A[i]);
    scanf("\n");
    for (int i = 0; i < n; ++i) gets(B[i]);

    construct();
    printf("%d\n", graph.compute(SRC, DST));

    return 0;
}
